1	import { createRequire } from 'module';
2	const require = createRequire(import.meta.url);
3	import { GameState, Result, Item, SkillId, EquipmentSlot, NPC, SovereignAvatar, ok, err } from '../../core/models.js';
4	import { SovereignAvatarEntity } from '../../core/SovereignAvatar.js';
5	import { GameplayModule } from '../../engines/gameplay/MinigameInterfaces.js';
6	import { createLogger } from '../../utils/logger.js';
7	import { CloudflareSyncLimb } from './CloudflareSyncLimb.js';
8	import { SwitchboardLimb } from '../../monitor/SwitchboardLimb.js';
9	import { EntityLimb } from '../technical/EntityLimb.js';
10	import { getSovereignRoot, resolveSovereignPath } from '../../utils/SovereignPathResolver.js';
11	import * as fs from 'fs';
12	import * as path from 'path';
13	import { SimulationHarness } from '../../engines/gameplay/SimulationHarness.js';
14	import { WorldGroundingLimb } from '../world_grounding/WorldGroundingLimb.js';
15	import { HexagramManager } from '../../routing/HexagramManager.js';
16	import { AIDispatcher } from '../../api/ai/Dispatcher.js';
17	import { ModelClient } from '../../clients/ModelClient.js';
18	import { SovereignConfig } from '../../config/SovereignConfig.js';
19	import { TernaryRouter } from '../../routing/TernaryRouter.js';
20	import { Renderer } from '../../ui/Renderer.js';
21	import { CombatLimb } from './CombatLimb.js';
22	import { BankLimb } from './BankLimb.js';
23	import { ItemLifecycleLimb } from './ItemLifecycleLimb.js';
24	import { AvatarStateLimb } from './AvatarStateLimb.js';
25	
26	const logger = createLogger('GameplaySovereigntyLimb');
27	
28	// Pedagogical Mappings
29	const CURRENCY_COINS = 22159;
30	const BANK_BUTTON_DEPOSIT_ALL = 141184642;
31	const BANK_BUTTON_DEPOSIT_EQUIPMENT = 141184643;
32	
33	export class GameplaySovereigntyLimb {
34	    private static instance: GameplaySovereigntyLimb | undefined;
35	    private isRunning: boolean = false;
36	    private tickInterval: NodeJS.Timeout | null = null;
37	    public tickCount: number = 0;
38	    /** Dirty flag — set on any state mutation, cleared after disk write */
39	    private stateDirty: boolean = false;
40	    
41	    public edgeSync: CloudflareSyncLimb;
42	    private switchboard: SwitchboardLimb | null = null;
43	    private entityBrain: EntityLimb | null = null;
44	    private harness: SimulationHarness | null = null;
45	    public combat: CombatLimb;
46	    public items: ItemLifecycleLimb;
47	    public bankLimb: BankLimb;
48	    public avatarState: AvatarStateLimb;
49	    public playerAgent: any; // PlayerAgent brain
50	    
51	    public globalState: GameState = {
52	        plane: 0,
53	        tickNumber: 0,
54	        players: new Map(),
55	        npcMap: new Map(),
56	        npcSpatialIndex: new Map(),
57	        objectMap: new Map(),
58	        groundItems: new Map(),
59	        graves: new Map(),
60	        varps: new Map(),
61	        varcs: new Map(),
62	        varbits: new Map(),
63	        lastTickTime: Date.now()
64	    };
65	
66	    public avatar: SovereignAvatar;
67	    private modules: Map<string, GameplayModule> = new Map();
68	    private activeModuleName: string | null = null;
69	
70	    protected constructor() {
71	        if (GameplaySovereigntyLimb.instance) {
72	            throw new Error('Singleton violation: use GameplaySovereigntyLimb.getInstance()');
73	        }
74	        this.avatar = new SovereignAvatarEntity('POG2_Sovereign');
75	        this.globalState.players.set(this.avatar.username, this.avatar as any);
76	        this.edgeSync = new CloudflareSyncLimb();
77	        this.combat = CombatLimb.getInstance();
78	        this.items = ItemLifecycleLimb.getInstance();
79	        this.bankLimb = BankLimb.getInstance();
80	        this.avatarState = AvatarStateLimb.getInstance();
81	        this.avatarState.bindEntity(this.avatar as SovereignAvatarEntity);
82	        
83	        // --- PHASE 72: GROUNDING THE PLAYER TEMPLATE ---
84	        const templatePath = path.join(process.cwd(), 'public', 'sovereign_entity_player.json');
85	        if (fs.existsSync(templatePath)) {
86	            try {
87	                const template = JSON.parse(fs.readFileSync(templatePath, 'utf8'));
88	                (this.avatar as SovereignAvatarEntity).hydrate(template);
89	                logger.info({ npcId: template.entity?.npcId }, 'Avatar grounded in public player template.');
90	            } catch (err) {
91	                logger.error({ err }, 'Failed to ground avatar in player template.');
92	            }
93	        }
94	        
95	        this.playerAgent = null; // Lazy loaded via engagePlayerHarness()
96	        
97	        this.loadSovereignState();
98	
99	        // Phase 112: Hook state changes to Switchboard for real-time viewport sync
100	        (this.avatar as SovereignAvatarEntity).onStateChange = (type, delta) => {
101	            if (this.switchboard) {
102	                this.switchboard.broadcast({
103	                    type: 'AVATAR_STATE_CHANGE',
104	                    payload: {
105	                        type,
106	                        delta,
107	                        username: this.avatar.username,
108	                        timestamp: Date.now()
109	                    }
110	                });
111	            }
112	        };
113	
114	        logger.info('GameplaySovereigntyLimb booted as a CNS-authoritative node.');
115	    }
116	
117	    public engagePlayerHarness() {
118	        if (!this.playerAgent) {
119	            const { PlayerAgent } = require('../../engines/gameplay/PlayerAgent.js');
120	            this.playerAgent = new PlayerAgent(this.avatar as SovereignAvatarEntity);
121	            logger.info("Player Harness Engaged via explicit VOLITION (pog2 play or chat command).");
122	        }
123	    }
124	
125	    public static getInstance(): GameplaySovereigntyLimb {
126	        if (!this.instance) {
127	            this.instance = new GameplaySovereigntyLimb();
128	        }
129	        return this.instance;
130	    }
131	
132	    public static resetInstance(): void {
133	        if (process.env.NODE_ENV === 'production') {
134	            throw new Error('resetInstance is forbidden in production');
135	        }
136	        this.instance = undefined;
137	    }
138	
139	    public injectSwitchboard(switchboard: SwitchboardLimb) {
140	        this.switchboard = switchboard;
141	        logger.info('Switchboard Bridge injected into Gameplay Limb.');
142	    }
143	
144	    public injectEntityLimb(entityLimb: EntityLimb) {
145	        this.entityBrain = entityLimb;
146	        logger.info('Entity Brain injected into Gameplay Limb.');
147	    }
148	
149	    private loadSovereignState() {
150	        const statePath = resolveSovereignPath('memory/sovereign_state.json');
151	        if (fs.existsSync(statePath)) {
152	            try {
153	                const data = JSON.parse(fs.readFileSync(statePath, 'utf8'));
154	                if (data.origin) {
155	                    this.avatar.coord.x = data.origin.x;
156	                    this.avatar.coord.y = data.origin.z; 
157	                    this.avatar.coord.plane = data.origin.plane;
158	                } else if (data.x !== undefined && data.y !== undefined) {
159	                    // [LEGACY MIGRATION] Support old RSC Save Format
160	                    this.avatar.coord.x = data.x;
161	                    this.avatar.coord.y = data.y;
162	                    this.avatar.coord.plane = 0; // RSC default
163	                    logger.info({ x: data.x, y: data.y }, '[SOVEREIGN PERSISTENCE] Legacy RSC origin coordinates ingested.');
164	                }
165	
166	                if (data.inventory) {
167	                    this.avatar.inventory = data.inventory;
168	                }
169	                if (data.bank) {
170	                    this.avatar.bank = data.bank;
171	                }
172	                if (data.wallet) {
173	                    this.avatar.wallet = data.wallet;
174	                }
175	
176	                if (data.skills) {
177	                    // Detect legacy named skills object vs POG2 ID-based object
178	                    if (data.skills.attack && typeof data.skills.attack.experience === 'number') {
179	                        // [LEGACY MIGRATION] Map RSC string keys to RS3 IDs
180	                        const rscSkillMap: Record<string, number> = {
181	                            attack: 1, defense: 5, strength: 2, hits: 6, ranged: 3, prayer: 7, magic: 4,
182	                            cooking: 16, woodcutting: 18, fletching: 19, fishing: 15, firemaking: 17,
183	                            crafting: 11, smithing: 14, mining: 13, herblaw: 9, agility: 8, thieving: 10
184	                        };
185	                        for (const [rscName, skillData] of Object.entries(data.skills)) {
186	                            const rs3Id = rscSkillMap[rscName];
187	                            if (rs3Id) {
188	                                const s = skillData as any;
189	                                this.avatar.skills[rs3Id] = {
190	                                    id: rs3Id,
191	                                    name: rscName.toUpperCase(),
192	                                    level: s.base || s.current || 1,
193	                                    xp: s.experience || 0
194	                                };
195	                            }
196	                        }
197	                        logger.info('[SOVEREIGN PERSISTENCE] Legacy RSC skills migrated to RS3 IDs.');
198	                    } else {
199	                        Object.entries(data.skills).forEach(([id, skill]: [string, any]) => {
200	                            this.avatar.skills[parseInt(id)] = skill;
201	                        });
202	                    }
203	                }
204	
205	                if (data.quests) {
206	                    this.avatar.quests = data.quests;
207	                } else if (data.questStages) {
208	                    // Legacy RSC Quest Stage mapping
209	                    this.avatar.quests = {
210	                        points: data.questPoints || 0,
211	                        completedCount: Object.keys(data.questStages).length,
212	                        quests: data.questStages
213	                    };
214	                }
215	
216	                if (data.varps) {
217	                    for (const [id, value] of Object.entries(data.varps)) {
218	                        this.globalState.varps.set(parseInt(id), value as number);
219	                    }
220	                }
221	                if (data.varbits) {
222	                    for (const [id, value] of Object.entries(data.varbits)) {
223	                        this.globalState.varbits.set(parseInt(id), value as number);
224	                    }
225	                }
226	                
227	                // Legacy custom RSC cache mapped to modern metadata
228	                if (data.cache) {
229	                    this.avatar.metadata = { ...this.avatar.metadata, legacyCache: data.cache };
230	                }
231	                logger.info({ origin: data.origin }, 'Loaded Sovereign Save State.');
232	            } catch (err) {
233	                logger.error({ err }, 'Failed to parse sovereign_state.json');
234	            }
235	        }
236	    }
237	
238	    public saveSovereignState() {
239	        const statePath = resolveSovereignPath('memory/sovereign_state.json');
240	        const state = {
241	            origin: {
242	                x: this.avatar.coord.x,
243	                z: this.avatar.coord.y,
244	                plane: this.avatar.coord.plane
245	            },
246	            inventory: this.avatar.inventory,
247	            bank: this.avatar.bank,
248	            wallet: this.avatar.wallet,
249	            skills: this.avatar.skills,
250	            quests: this.avatar.quests,
251	            varps: Object.fromEntries(this.globalState.varps),
252	            varbits: Object.fromEntries(this.globalState.varbits),
253	            timestamp: new Date().toISOString()
254	        };
255	        fs.writeFileSync(statePath, JSON.stringify(state, null, 2));
256	        this.stateDirty = false;
257	        logger.debug('Sovereign State Saved.');
258	    }
259	
260	    /** Mark state as dirty — call whenever any avatar field is mutated */
261	    public markDirty(): void {
262	        this.stateDirty = true;
263	    }
264	
265	
266	    /**
267	     * Handles interacting with the Bank (Nardah Banker Map)
268	     */
269	    public openBank() {
270	        logger.info('Banking interface manifest triggers. Syncing HUD IDs 141184642+');
271	        // Logic for bank UI population goes here...
272	    }
273	
274	    /**
275	     * Relief of Inventory -> Bank Transfer
276	     */
277	    public depositItem(slot: number, amount: number = 1) {
278	        const item = this.avatar.removeItem(slot);
279	        if (item) {
280	            const existing = this.avatar.bank.find(i => i.id === item.id);
281	            if (existing) {
282	                existing.amount += item.amount;
283	            } else {
284	                this.avatar.bank.push(item);
285	            }
286	            this.stateDirty = true;
287	            this.saveSovereignState();
288	        }
289	    }
290	
291	    /**
292	     * Achievement Trigger: Fruitful Labour (ID 346)
293	     */
294	    public triggerAchievement(id: number) {
295	        if (id === 346) {
296	            logger.info('Achievement: Fruitful Labour triggered. Rewarding 30 Coins.');
297	            this.awardCurrency(CURRENCY_COINS, 30);
298	        }
299	    }
300	
301	    private awardCurrency(id: number, amount: number) {
302	        this.avatar.wallet[id] = (this.avatar.wallet[id] || 0) + amount;
303	        this.stateDirty = true;
304	        this.saveSovereignState();
305	    }
306	
307	    /**
308	     * registerModule - Attach a new logic interpreter to the limb.
309	     */
310	    public registerModule(module: GameplayModule): void {
311	        this.modules.set(module.name.toLowerCase(), module);
312	        logger.info({ module: module.name }, 'Gameplay module registered.');
313	    }
314	
315	    /**
316	     * setActiveModule - Docks a specific Region/Minigame logic module onto the active server.
317	     */
318	    public async setActiveModule(name: string): Promise<Result<boolean>> {
319	        const module = this.modules.get(name.toLowerCase());
320	        if (!module) return err(new Error(`Module '${name}' not found.`));
321	
322	        if (this.activeModuleName) {
