8	import { getDashboardPath } from './SovereignPathResolver.js';
9	import { createLogger } from "./logger.js";
10	
11	const execAsync = promisify(exec);
12	
13	const logger = createLogger('SovereignEye');
14	
15	/**
16	 * Capture source definition â€” what the Sovereign Eye is looking at.
17	 */
18	export type CaptureSource =
19	    | { type: 'url'; target: string }           // http://localhost:3000, wrangler dev, etc.
20	    | { type: 'html'; target: string }          // Path to .html file
21	    | { type: 'rsc'; target: 'game_client' }    // RSC client â€” delegates to RSCLimb state
22	    | { type: 'window'; target: string }        // OS window title match
23	    | { type: 'file'; target: string };          // Existing screenshot/image file
24	
25	/**
26	 * Result of a capture operation.
27	 */
28	export interface CaptureResult {
29	    readonly imagePath: string | null;           // Path to screenshot (null if text-only)
30	    readonly textContent: string | null;         // Scraped text content (for URL/HTML sources)
31	    readonly sourceType: CaptureSource['type'];
32	    readonly metadata: Record<string, unknown>;
33	    readonly timestamp: number;
34	}
35	
36	/**
37	 * Viewport configuration for captures.
38	 */
39	export interface ViewportConfig {
40	    readonly width: number;
41	    readonly height: number;
42	}
43	
44	const DEFAULT_VIEWPORT: ViewportConfig = { width: 1280, height: 720 };
45	
46	/**
47	 * SovereignEye â€” Universal capture engine.
48	 * 
49	 * Captures visual and textual state from ANY source: localhost dev servers,
50	 * wrangler dev environments, HTML files, OS windows, and existing images.
51	 * 
52	 * NO MOCKS â€” All captures come from real, running environments.
53	 */
54	export class SovereignEye extends EventEmitter {
55	    private readonly captureDir: string;
56	
57	    constructor(projectId: string = 'guest') {
58	        super();
59	        this.captureDir = join(getDashboardPath(projectId), 'sovereign_eye');
60	        if (!existsSync(this.captureDir)) {
61	            mkdirSync(this.captureDir, { recursive: true });
62	        }
63	    }
64	
65	    /**
66	     * Universal capture entry point.
67	     */
68	    async capture(source: CaptureSource, viewport: ViewportConfig = DEFAULT_VIEWPORT): Promise<Result<CaptureResult>> {
69	        logger.info({ sourceType: source.type, target: source.target }, 'Sovereign Eye capturing');
70	
71	        switch (source.type) {
72	            case 'url':
73	                return this.captureUrl(source.target, viewport);
74	            case 'html':
75	                return this.captureHtmlFile(source.target, viewport);
76	            case 'rsc':
77	                return this.captureRSC();
78	            case 'window':
79	                return this.captureWindow(source.target);
80	            case 'file':
81	                return this.captureFile(source.target);
82	            default:
83	                return { ok: false, error: new Error(`Unknown capture source type`) };
84	        }
85	    }
86	
87	    /**
88	     * Capture a URL target (localhost, wrangler dev, deployed page).
89	     */
90	    private async captureUrl(url: string, viewport: ViewportConfig): Promise<Result<CaptureResult>> {
91	        const timestamp = Date.now();
92	        const screenshotPath = join(this.captureDir, `url_${timestamp}.png`);
93	
94	        try {
95	            // 1. Attempt headless Chrome/Edge screenshot
96	            const screenshotResult = await this.headlessScreenshot(url, screenshotPath, viewport);
97	
98	            // 2. Always fetch text content as fallback/supplement
99	            let textContent: string | null = null;
100	            let attempts = 0;
101	            const maxAttempts = 3;
102	
103	            while (attempts < maxAttempts && !textContent) {
104	                attempts++;
105	                try {
106	                    const controller = new AbortController();
107	                    const timeoutId = setTimeout(() => controller.abort(), 15000); // Extended to 15s
108	                    
109	                    const response = await undiciFetch(url, { 
110	                        signal: controller.signal,
111	                        headers: { 'User-Agent': 'SovereignEye/2.0' }
112	                    });
113	                    clearTimeout(timeoutId);
114	                    
115	                    if (response.ok) {
116	                        textContent = await response.text();
117	                        // Trim for AI context
118	                        if (textContent.length > 10000) {
119	                            textContent = textContent.substring(0, 10000) + '\n... [truncated]';
120	                        }
121	                    } else {
122	                        throw new Error(`HTTP ${response.status}`);
123	                    }
124	                } catch (fetchErr: any) {
125	                    const isTimeout = fetchErr.name === 'AbortError' || fetchErr.message?.includes('Timeout');
126	                    if (attempts < maxAttempts) {
127	                        logger.warn({ url, attempt: attempts, isTimeout }, 'Text fetch failed, retrying...');
128	                        await new Promise(res => setTimeout(res, 2000 * attempts)); // Exponential backoff
129	                    } else {
130	                        if (isTimeout) {
131	                            logger.warn({ url }, 'Text fetch timed out (15s) after 3 attempts, screenshot-only mode');
132	                        } else {
133	                            logger.warn({ err: fetchErr.message, url }, 'Text fetch failed after 3 attempts, screenshot-only mode');
134	                        }
135	                    }
136	                }
137	            }
138	
139	            if (!screenshotResult.ok && !textContent) {
140	                return { ok: false, error: new Error(`Capture failed: No screenshot and no text content could be retrieved.`) };
141	            }
142	
143	            const result: CaptureResult = {
144	                imagePath: screenshotResult.ok ? screenshotPath : null,
145	                textContent,
146	                sourceType: 'url',
147	                metadata: { url, viewport, hasScreenshot: screenshotResult.ok },
148	                timestamp
149	            };
150	
151	            if (screenshotResult.ok) {
152	                await this.cleanupOldCaptures();
153	            }
154	
155	            this.emit('capture', result);
156	
157	            return {
158	                ok: true,
159	                value: result
160	            };
161	        } catch (err) {
162	            return { ok: false, error: err as Error };
163	        }
164	    }
165	
166	    /**
167	     * Capture a local HTML file.
168	     */
169	    private async captureHtmlFile(filePath: string, viewport: ViewportConfig): Promise<Result<CaptureResult>> {
170	        const absPath = resolve(filePath);
171	        if (!existsSync(absPath)) {
172	            return { ok: false, error: new Error(`HTML file not found: ${absPath}`) };
